class MaterializedDisclosureItem:
    """Keep rendered information separate from its native supporting value."""

    option_identity: str
    representation: str
    resource_addresses: tuple[RepositoryResourceAddress, ...]
    content_identities: tuple[ContentIdentity, ...]
    text: str
